// Project intake validation (pure). Regulatory review status is OPERATOR INPUT with a reviewer and a date;
// it is never generated by Titan Ghost Intelligence and any client-supplied provenance is overwritten.
import { REG_STATUSES } from './model.mjs';

const ID_RE = /^[a-z0-9][a-z0-9-]{2,40}$/;
const R_ADDR = /^r[1-9A-HJ-NP-Za-km-z]{24,34}$/;
const CUR_RE = /^([A-Za-z0-9?!@#$%^&*<>(){}[\]|]{3}|[0-9A-Fa-f]{40})$/;
export const TOKEN_NETWORKS = ['testnet', 'mainnet', 'not_yet_selected'];
const str = (v, max = 4000) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const num = (v) => (typeof v === 'string' && v.trim() !== '' ? Number(v) : v);
const isoDay = (v) => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}/.test(v) && !Number.isNaN(Date.parse(v));

export function validateRegulatoryReview(r = {}, { now = Date.now() } = {}) {
  const errors = [];
  const status = r.status;
  if (!REG_STATUSES.includes(status)) errors.push(`regulatoryReview.status must be one of ${REG_STATUSES.join(', ')}.`);
  const reviewer = str(r.reviewer, 120), date = str(r.date, 40);
  if (status && status !== 'NOT_STARTED') {
    if (!reviewer) errors.push('regulatoryReview.reviewer is required (operator-entered name of the reviewer).');
    if (!isoDay(date)) errors.push('regulatoryReview.date is required (YYYY-MM-DD).');
    else if (Date.parse(date) > now + 86_400_000) errors.push('regulatoryReview.date cannot be in the future.');
  }
  return { errors, value: { status, reviewer: reviewer || null, date: date || null, notes: str(r.notes, 1000) || null, source: 'OPERATOR_INPUT', aiGenerated: false } };
}

export function validateIntake(b = {}, { now = Date.now(), existingIds = [] } = {}) {
  const errors = [];
  const id = str(b.id, 41).toLowerCase();
  if (!ID_RE.test(id)) errors.push('id must be 3–41 chars: lowercase letters, digits, hyphens.');
  else if (existingIds.includes(id)) errors.push(`Project id ${id} already exists.`);
  const name = str(b.name, 80); if (name.length < 3) errors.push('name is required (3–80 chars).');
  const description = str(b.description, 2000); if (description.length < 20) errors.push('description (business description) must be at least 20 characters.');

  let token = null;
  if (b.token != null) {
    const t = b.token;
    const network = t.network || 'not_yet_selected';
    if (!TOKEN_NETWORKS.includes(network)) errors.push(`token.network must be one of ${TOKEN_NETWORKS.join(', ')}.`);
    const currency = str(t.currency, 40);
    if (!CUR_RE.test(currency) || currency.toUpperCase() === 'XRP') errors.push('token.currency must be a 3-character code (not XRP) or 40-hex currency code.');
    const issuedFlag = t.issuer && t.issuer !== 'NOT_YET_ISSUED';
    if (issuedFlag && !R_ADDR.test(t.issuer)) errors.push('token.issuer must be a classic r-address, or "NOT_YET_ISSUED".');
    token = { network, currency, issuer: issuedFlag ? t.issuer : null, issued: !!issuedFlag };
  }

  const rr = validateRegulatoryReview(b.regulatoryReview || {}, { now });
  errors.push(...rr.errors);

  const requestedUsd = num(b.requestedUsd);
  if (!(typeof requestedUsd === 'number' && Number.isFinite(requestedUsd) && requestedUsd > 0 && requestedUsd <= 1_000_000_000)) errors.push('requestedUsd must be > 0 and ≤ 1,000,000,000.');
  const months = num(b.targetOperatingPeriod?.months ?? b.targetOperatingMonths);
  if (!(Number.isInteger(months) && months >= 1 && months <= 60)) errors.push('targetOperatingPeriod.months must be an integer 1–60.');
  const sustainability = str(b.sustainabilityMeasures, 2000); if (sustainability.length < 10) errors.push('sustainabilityMeasures must describe how the business sustains itself (≥ 10 chars).');
  const runwayMonths = num(b.runwayMonths ?? 0);
  if (!(typeof runwayMonths === 'number' && runwayMonths >= 0 && runwayMonths <= 240)) errors.push('runwayMonths must be 0–240.');

  const e = b.mmEconomics || {};
  const mmEconomics = { targetSpreadBps: num(e.targetSpreadBps ?? 50), minDepthUsd: num(e.minDepthUsd ?? 10_000), maxInventorySkewPct: num(e.maxInventorySkewPct ?? 30), notes: str(e.notes, 1000) || null };
  if (!(mmEconomics.targetSpreadBps > 0 && mmEconomics.targetSpreadBps <= 5000)) errors.push('mmEconomics.targetSpreadBps must be 1–5000.');
  if (!(mmEconomics.minDepthUsd >= 0 && mmEconomics.minDepthUsd <= 1e9)) errors.push('mmEconomics.minDepthUsd must be ≥ 0.');
  if (!(mmEconomics.maxInventorySkewPct >= 0 && mmEconomics.maxInventorySkewPct <= 100)) errors.push('mmEconomics.maxInventorySkewPct must be 0–100.');

  const desiredMarkets = (Array.isArray(b.desiredMarkets) ? b.desiredMarkets : String(b.desiredMarkets || '').split(','))
    .map((m) => str(m, 40)).filter(Boolean).slice(0, 12);
  if (!desiredMarkets.length) errors.push('desiredMarkets: list at least one desired future market (e.g. TOKEN/XRP).');

  return {
    ok: errors.length === 0, errors,
    value: { id, name, description, token, regulatoryReview: rr.value, requestedUsd, targetOperatingPeriod: { months }, sustainabilityMeasures: sustainability,
      runwayMonths, mmEconomics, desiredMarkets, radarId: str(b.radarId, 200) || null },
  };
}
